SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS existence FROM bt_agent_skill WHERE status_cd = '00A' AND skill_name = #{skillName}
AND ( tenant_id = -1 OR (tenant_id = #{tenantId} AND data_from = '10A' AND creator_id = #{creatorId}) )
AND tenant_id IN (#{tenantId}, -1) AND (data_from is null or data_from = '')

SELECT a.skill_id, a.tenant_id, a.bot_id, a.skill_name, a.skill_code, a.catalog_item_id, a.file_info_id, a.data_from, a.skill_square_id, a.skill_version
FROM bt_agent_skill a
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.skill_square_id = #{skillSquareId}


    AND a.creator_id = #{creatorId}
    AND a.data_from = '10A'


    AND (a.data_from IS NULL OR a.data_from = '')

