SELECT a.skill_id, a.tenant_id, a.skill_name, a.skill_code, a.remark AS skill_desc, CASE WHEN b.online_status = 'T' THEN 1 ELSE 0 END AS published FROM bt_agent_skill a LEFT JOIN bt_agent_skill_square b ON b.skill_code = a.skill_code AND b.status_cd = '00A' WHERE a.status_cd = '00A' AND a.data_from = '10A' AND a.tenant_id = #{params.spaceId} AND a.creator_id = #{params.userId} AND a.skill_square_id IS NULL
AND a.skill_name LIKE #{params.keyword}
ORDER BY a.updated_time DESC

SELECT count(1)
FROM bt_agent_skill a
WHERE a.status_cd = '00A'


    AND a.data_from = '10A'
    AND a.tenant_id = #{spaceId}
    AND a.creator_id = #{userId}
    AND a.skill_square_id IS NULL


    AND a.tenant_id = #{tenantId}
    AND (a.data_from IS NULL OR a.data_from = '')

SELECT a.skill_square_id, a.skill_id, a.tenant_id, a.skill_name, a.skill_code, a.skill_version AS version,
       b.skill_desc, b.skill_type
FROM bt_agent_skill a
LEFT JOIN bt_agent_skill_square b ON b.skill_id = a.skill_square_id
WHERE a.status_cd = '00A'
  AND a.data_from = '10A'
  AND a.tenant_id = #{params.spaceId}
  AND a.creator_id = #{params.userId}
  AND a.skill_square_id IS NOT NULL

  AND b.skill_type = #{params.skillType}


  AND a.skill_name LIKE #{params.keyword}

ORDER BY a.updated_time DESC

SELECT COUNT(DISTINCT a.skill_square_id)
FROM bt_agent_skill a
WHERE a.status_cd = '00A'


    AND a.data_from = '10A'
    AND a.tenant_id = #{spaceId}
    AND a.creator_id = #{userId}
    AND a.skill_square_id IS NOT NULL


    AND a.tenant_id = #{tenantId}
    AND (a.data_from IS NULL OR a.data_from = '')
